import gurobipy as gp
from gurobipy import GRB
T = []
r = []
for rec in LEGACY_RECORDS:
    T.append(rec['values']['Time'])
    r.append(int(rec['values']['Requirement']))
n = len(T)
if n != 48:
    raise ValueError(f'Expected 48 intervals, got {n}')
m = gp.Model('Waitstaff_Scheduling')
x = m.addVars(range(n), lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((x[t] for t in range(n))), GRB.MINIMIZE)
for s in range(n):
    m.addConstr(gp.quicksum((x[(s - k) % n] for k in range(8))) >= r[s], name=f'demand_{s}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for t in range(n):
        print(f'x[{T[t]}]: {x[t].X}')
else:
    print(f'Solver status: {m.Status}')